<x-layouts.app :heading="$release->exists ? 'Edit release' : 'New release'"><form class="panel form-grid" method="post" action="{{ $release->exists ? route('releases.update',$release) : route('releases.store') }}">@csrf @if($release->exists)@method('PUT')@endif<label>Product<select name="product_id"><option value="">No linked product</option>@foreach($products as $product)<option value="{{ $product->id }}" @selected(old('product_id',$release->product_id)==$product->id)>{{ $product->code }} — {{ $product->name }}</option>@endforeach</select></label><label>Project<input name="project" value="{{ old('project',$release->project) }}" required></label><label>Version<input name="version" value="{{ old('version',$release->version) }}" required></label><label>Release type<select name="release_type"><option value="PRODUCTION">Production</option><option value="MAINTENANCE">Maintenance</option><option value="EMERGENCY">Emergency</option></select></label><label class="wide">Description<textarea name="description" rows="5" required>{{ old('description',$release->description) }}</textarea></label>@unless($release->exists)<label class="wide">Components <small>One component per line</small><textarea name="components" rows="4" placeholder="Control module&#10;Safety documentation"></textarea></label>@endunless<div class="wide form-actions"><a class="btn" href="{{ route('releases.index') }}">Cancel</a><button class="btn primary">Save release</button></div></form></x-layouts.app>
